/**
 * MailAgent: Headless JavaScript SDK gửi và nhận email 2 chiều
 * Thành viên phụ trách: Thành viên 2
 */

(function (window) {
  const listeners = {};

  // Khởi tạo WebSocket lắng nghe thư mới
  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  const wsUrl = `${protocol}//${window.location.host}`;
  let socket = null;

  function initSocket() {
    try {
      socket = new WebSocket(wsUrl);
      socket.onmessage = (event) => {
        try {
          const payload = JSON.parse(event.data);
          if (payload.type === 'INBOUND_MAIL' && listeners['mail:received']) {
            listeners['mail:received'].forEach(fn => fn(payload.data));
          }
          if (payload.type === 'NEW_MAIL' && listeners['mail:sent']) {
            listeners['mail:sent'].forEach(fn => fn(payload.data));
          }
        } catch (e) {
          console.error(e);
        }
      };
      socket.onclose = () => {
        setTimeout(initSocket, 3000); // Tự động kết nối lại
      };
    } catch (err) {
      console.warn('[MailAgent] Chưa thể mở kết nối WebSocket.');
    }
  }

  initSocket();

  const MailAgent = {
    // Gửi email bất đồng bộ
    send: async function (options) {
      const { to, subject, text, html } = options;
      if (!to) throw new Error('[MailAgent] Thiếu trường "to"');

      const response = await fetch('/api/v1/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ to, subject, text, html })
      });

      return await response.json();
    },

    // Lắng nghe sự kiện
    on: function (eventName, callback) {
      if (!listeners[eventName]) listeners[eventName] = [];
      listeners[eventName].push(callback);
    }
  };

  window.MailAgent = MailAgent;
})(window);
